VALUES (62710, 'tt4474344', NULL, 'Blindspot', 'Blindspot', 'tv', 2015, 'https://image.tmdb.org/t/p/w500/4AeYzamQmd9Fa6hawDmYKbdvBSe.jpg', 'https://image.tmdb.org/t/p/original/1GWiao0QYuKsoTvUmd7ivnE3qDY.jpg', 'A vast international plot explodes when a beautiful Jane Doe is discovered naked in Times Square, completely covered in mysterious, intricate tattoos with no memory of who she is or how she got there. But there''s one tattoo that is impossible to miss: the name of FBI agent Kurt Weller, emblazoned across her back. "Jane," Agent Weller and the rest of the FBI quickly realize that each mark on her body is a crime to solve, leading them closer to the truth about her identity and the mysteries to be revealed.', NULL, NULL, 58.3833, 7.379, 0, 1.01, '2026-10-21 05:03:47', '2026-10-21 05:03:47')
