VALUES (212076, 'tt16287610', NULL, 'Send Help', 'Send Help', 'tv', 2022, 'https://image.tmdb.org/t/p/w500/lEH3UvgGVC0TP0pszGZ9VVms4oa.jpg', 'https://image.tmdb.org/t/p/original/bhFVqvEKUuDz6KVdOaCfYmsIXeo.jpg', 'Haitian American actor Fritz Jean-Baptiste is riding high as the star of the fictional hit TV show, “This Can’t Be Us.” Convinced that the good times will roll on forever, he thwarts all other career advancing opportunities as he plays the field with multiple women, instead of tackling a family tragedy that is beginning to unravel his entire life.', NULL, NULL, 3.6263, 0.0, 0, 8.01, '2026-10-21 05:03:47', '2026-10-21 05:03:47')
