VALUES (438631, 'tt1160419', NULL, 'Dune', 'Dune', 'movie', 2021, 'https://image.tmdb.org/t/p/w500/gDzOcq0pfeCeqMBwKIJlSmQpjkZ.jpg', 'https://image.tmdb.org/t/p/original/qVgZu5BTx6pu4owCvVOm4zjTfOi.jpg', 'Paul Atreides, a brilliant and gifted young man born into a great destiny beyond his understanding, must travel to the most dangerous planet in the universe to ensure the future of his family and his people. As malevolent forces explode into conflict over the planet''s exclusive supply of the most precious resource in existence - a commodity capable of unlocking humanity''s greatest potential - only those who can conquer their fear will survive.', NULL, NULL, 32.1831, 7.784, 0, 6.63636065573770537e+01, '2026-07-15 12:01:52', '2026-10-21 05:03:47')
