VALUES (75612, 'tt1483013', NULL, 'Oblivion', 'Oblivion', 'movie', 2013, 'https://image.tmdb.org/t/p/w500/bYLM3GpNUZnoFElPXp1zlhDPdtv.jpg', 'https://image.tmdb.org/t/p/original/2kVt8oj1cSz4GAP0Hi8SESOiH0T.jpg', 'Jack Harper is one of the last few drone repairmen stationed on Earth. Part of a massive operation to extract vital resources after decades of war with a terrifying threat known as the Scavs, Jack’s mission is nearly complete. His existence is brought crashing down when he rescues a beautiful  stranger from a downed spacecraft. Her arrival triggers a chain of events that  forces him to question everything he knows and puts the fate of humanity in his hands.', NULL, NULL, 9.7316, 6.686, 0, 3.86354838709677466e+01, '2026-07-15 12:01:52', '2026-10-21 05:03:47')
