VALUES (10442, 'tt0108174', NULL, 'So I Married an Axe Murderer', 'So I Married an Axe Murderer', 'movie', 1993, 'https://image.tmdb.org/t/p/w500/zQlpQDKDADKlgqfMs1E191ofDJU.jpg', 'https://image.tmdb.org/t/p/original/iVweNwFhEtlJlPxOkaDh8VboE9b.jpg', 'Just after a bad breakup, Charlie MacKenzie falls for lovely butcher Harriet Michaels and introduces her to his parents. But, as voracious consumers of sensational tabloids, his parents soon come to suspect that Harriet is actually a notorious serial killer -- "Mrs. X" -- wanted in connection with a string of bizarre honeymoon killings. Thinking his parents foolish, Charlie proposes to Harriet. But while on his honeymoon with her, he begins to fear they were right.', NULL, NULL, 3.3217, 6.113, 0, 1.50114285714285706e+01, '2026-07-15 12:01:52', '2026-10-21 05:03:47')
