VALUES (9326, 'tt0088011', NULL, 'Romancing the Stone', 'Romancing the Stone', 'movie', 1984, 'https://image.tmdb.org/t/p/w500/qfIlVOYZH5RiZ0ndFKUpr5Zn2Bx.jpg', 'https://image.tmdb.org/t/p/original/t2JVeiLvv3k7KlHFUou8tkrMZTN.jpg', 'Though she can spin wild tales of passionate romance, novelist Joan Wilder has no life of her own. Then one day adventure comes her way in the form of a mysterious package. It turns out that the parcel is the ransom she''ll need to free her abducted sister, so Joan flies to South America to hand it over. But she gets on the wrong bus and winds up hopelessly stranded in the jungle.', NULL, NULL, 6.6227, 6.8, 0, 2.20366666666666652e+01, '2026-07-20 04:02:06', '2026-10-21 05:03:47')
