VALUES (22586, 'tt0111333', NULL, 'The Swan Princess', 'The Swan Princess', 'movie', 1994, 'https://image.tmdb.org/t/p/w500/f5YvIPrkJ9HCsNbgzWJJyxXVNhj.jpg', 'https://image.tmdb.org/t/p/original/hKXmvyBGkyIYfKPAgJdH40q1ozh.jpg', 'The beautiful princess Odette is transformed into a swan by an evil sorcerer''s spell. Held captive at an enchanted lake, she befriends Jean-Bob the frog, Speed the turtle and Puffin the bird. Despite their struggle to keep the princess safe, these good-natured creatures can do nothing about the sorcerer''s spell, which can only be broken by a vow of everlasting love.', NULL, NULL, 4.2454, 6.629, 0, 13.90875, '2026-08-04 03:20:13', '2026-10-21 05:03:47')
