VALUES (49530, 'tt1637688', NULL, 'In Time', 'In Time', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/3Mwj2sIONQckOZP3YwsUXF7U5I4.jpg', 'https://image.tmdb.org/t/p/original/pxL08w7Eq0vKrQ3mJzYp0VHGaKG.jpg', 'In the not-too-distant future, the aging gene has been switched off. To avoid overpopulation, time has become the currency and the way people pay for luxuries and necessities. The rich can live forever, while the rest struggle to negotiate for their immortality. A poor young man who suddenly comes into a fortune of time finds himself on the run from a corrupt police force known as the "time keepers".', NULL, NULL, 13.8073, 6.972, 0, 10.395, '2026-08-11 22:09:33', '2026-10-21 05:03:47')
